iption":"JSON-LD structured data, Open Graph tags, sitemap, and robots.txt in place.","clientApprovalRequired":false},{"id":"documentation","name":"System Documentation","description":"All account URLs, credentials references, and system documentation delivered to client.","clientApprovalRequired":false},{"id":"training","name":"Client Training","description":"HubSpot CRM and Google Business Profile training completed and signed off.","clientApprovalRequired":true}],"training":[{"id":"hubspot","name":"HubSpot CRM","scope":"Initial orientation — navigating contacts, reviewing form submissions, understanding the lead workflow, and basic CRM management.","competencies":["Can log in to HubSpot independently","Can view and navigate the Contacts list","Can open a contact record and review activity","Can understand what happens when a form is submitted","Can locate and review form submissions","Understands how the confirmation and notification emails work"]},{"id":"gbp","name":"Google Business Profile","scope":"Initial orientation — managing business information, responding to reviews, and posting Google Business updates.","competencies":["Can log in to Google Business Profile independently","Can update business hours and contact information","Can respond to Google reviews","Can create and publish a Google Business post","Can view basic insights (searches, clicks, calls)"]},{"id":"website-cms","name":"Website & GitHub","scope":"Basic orientation — understanding how the website is hosted, how to make simple text changes, and who to contact for larger updates.","competencies":["Understands how the website is hosted (Cloudflare Pages via GitHub)","Knows how to contact Laminar for content updates","Can identify which sections are visible vs. pending (hidden) on the site","Understands what triggers a site re-deploy"]}]}'::jsonb),
